                } else {
                    let (esc, needs) = escape_filename(&fpath);
                    if needs {
                        println!("\\{}  {}", hex, esc);
                    } else {
                        // For "-" file, fpath is "-"
                        println!("{}  {}", hex, fpath);
                    }
                }
            }
        }

        if any_error {
            std::process::exit(1);
        }
    }
}
