            Ok(v) => v,
            Err(_) => {
                eprintln!("error: invalid value '{}' for '--length <LEN>': invalid digit found in string", s);
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        }
    };

    let seek_val: u64 = {
        let s = matches.get_one::<String>("seek").unwrap();
        match s.parse::<u64>() {
            Ok(v) => v,
            Err(_) => {
                if s.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found", s);
                    eprintln!();
                    eprintln!("  tip: to pass '{}' as a value, use '-- {}'", s, s);
                    eprintln!();
                    eprintln!("Usage: executable [OPTIONS] [FILE]...");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                } else {
                    eprintln!("error: invalid value '{}' for '--seek <SEEK>': invalid digit found in string", s);
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        }
    };

    if let Some(nt_str) = matches.get_one::<String>("num-threads") {
        if nt_str.parse::<u64>().is_err() {
            eprintln!("error: invalid value '{}' for '--num-threads <NUM>': invalid digit found in string", nt_str);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if is_check {
        let check_files = if files.is_empty() { vec!["-".to_string()] } else { files.clone() };
        let mut any_failed = false;
        let mut total_failed = 0u64;
        for cf_path in check_files {
            let content: Vec<u8> = if cf_path == "-" {
                let mut buf = Vec::new();
                io::stdin().read_to_end(&mut buf).unwrap();
                buf
            } else {
                match std::fs::read(&cf_path) {
                    Ok(b) => b,
                    Err(e) => {
                        eprintln!("Error: No such file or directory (os error {})", e.raw_os_error().unwrap_or(2));
                        any_failed = true;
                        continue;
                    }
                }
            };
            let text = String::from_utf8_lossy(&content);
            for line in text.lines() {
                if line.is_empty() {
                    eprintln!("b3sum: Empty line");
                    any_failed = true;
                    total_failed += 1;
                    continue;
                }
                let mut is_escaped = false;
                let mut line_to_parse = line;
                if line.starts_with('\\') {
                    is_escaped = true;
                    line_to_parse = &line[1..];
                }

                // parse
                let mut fname_opt: Option<String> = None;
                let mut hash_opt: Option<String> = None;
                let mut parse_error = false;

                if line_to_parse.starts_with("BLAKE3 (") {
                    if let Some(eq_idx) = line_to_parse.rfind(" = ") {
                        let left = &line_to_parse[..eq_idx];
                        let right = &line_to_parse[eq_idx+3..];
                        if left.starts_with("BLAKE3 (") && left.ends_with(')') {
                            let inner = &left[7..left.len()-1];
                            let fname_res = if is_escaped {
                                unescape_filename(inner)
                            } else {
                                Ok(inner.to_string())
                            };
                            match fname_res {
                                Ok(f) => {
                                    if right.len() != 64 {
                                        eprintln!("b3sum: Invalid hash length");
                                        parse_error = true;
                                    } else if !right.chars().all(|c| c.is_ascii_hexdigit() && (c.is_ascii_digit() || (c >= 'a' && c <= 'f'))) {
                                        // Actually need to detect invalid hex vs length, but length already checked
                                        // For upper case, it's invalid hex
                                        eprintln!("b3sum: Invalid hex");
                                        parse_error = true;
                                    } else {
                                        fname_opt = Some(f);
                                        hash_opt = Some(right.to_string());
                                    }
                                }
                                Err(_) => {
                                    eprintln!("b3sum: Invalid backslash escape");
                                    parse_error = true;
                                }
                            }
                        } else {
                            eprintln!("b3sum: Invalid check line format");
                            parse_error = true;
                        }
                    } else {
                        eprintln!("b3sum: Invalid check line format");
                        parse_error = true;
                    }
                } else {
                    if let Some(idx) = line_to_parse.find("  ") {
                        let hash_part = &line_to_parse[..idx];
                        let file_part = &line_to_parse[idx+2..];
                        if file_part.is_empty() {
                            eprintln!("b3sum: empty file path");
                            parse_error = true;
                        } else if hash_part.len() != 64 {
                            eprintln!("b3sum: Invalid hash length");
                            parse_error = true;
                        } else if !hash_part.chars().all(|c| c.is_ascii_digit() || (c >= 'a' && c <= 'f')) {
                            // Check if all hex digits but maybe upper case => Invalid hex
                            let mut all_hex = true;
                            for ch in hash_part.chars() {
                                if !ch.is_ascii_hexdigit() {
                                    all_hex = false;
                                    break;
                                }
                            }
                            if !all_hex {
                                eprintln!("b3sum: Invalid hex");
                            } else {
                                eprintln!("b3sum: Invalid hex");
                            }
                            parse_error = true;
                        } else {
                            let fname_res = if is_escaped {
                                unescape_filename(file_part)
                            } else {
                                Ok(file_part.to_string())
                            };
                            match fname_res {
                                Ok(f) => {
                                    fname_opt = Some(f);
                                    hash_opt = Some(hash_part.to_string());
                                }
                                Err(_) => {
                                    eprintln!("b3sum: Invalid backslash escape");
                                    parse_error = true;
                                }
                            }
                        }
                    } else {
                        eprintln!("b3sum: Invalid check line format");
                        parse_error = true;
                    }
                }

                if parse_error {
                    any_failed = true;
                    total_failed += 1;
                    continue;
                }

                if let (Some(fname), Some(expected_hash)) = (fname_opt, hash_opt) {
                    let data = match std::fs::read(&fname) {
                        Ok(d) => d,
                        Err(e) => {
                            let (esc, needs) = escape_filename(&fname);
                            let display = if needs { format!("\\{}", esc) } else { esc };
                            println!("{}: FAILED (No such file or directory (os error {}))", display, e.raw_os_error().unwrap_or(2));
                            any_failed = true;
                            total_failed += 1;
                            continue;
                        }
                    };
                    let computed = hash_with_xof(&data, &IV, 0, &IV, seek_val, 32);
                    let computed_hex = computed.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                    let (esc, needs) = escape_filename(&fname);
                    let display = if needs { format!("\\{}", esc) } else { esc };
                    if computed_hex == expected_hash {
                        if !matches.get_flag("quiet") {
                            println!("{}: OK", display);
                        }
                    } else {
                        println!("{}: FAILED", display);
                        any_failed = true;
                        total_failed += 1;
                    }
                }
            }
        }
        if any_failed {
            eprintln!("b3sum: WARNING: {} computed checksum did NOT match", total_failed);
            std::process::exit(1);
        } else {
            std::process::exit(0);
        }
    } else {
        // hash mode
        let key_words: Option<[u32; 8]> = if is_keyed {
            let mut key_data = Vec::new();
            io::stdin().read_to_end(&mut key_data).unwrap();
            if key_data.len() > 32 {
                eprintln!("Error: read more than 32 key bytes from stdin");
                std::process::exit(1);
            }
            if key_data.len() != 32 {
                eprintln!("Error: expected 32 key bytes from stdin, found {}", key_data.len());
                std::process::exit(1);
            }
            let mut kw = [0u32; 8];
            for i in 0..8 {
                kw[i] = u32::from_le_bytes([key_data[i*4], key_data[i*4+1], key_data[i*4+2], key_data[i*4+3]]);
            }
            Some(kw)
        } else {
            None
        };

        let derive_ctx_cv: Option<[u32; 8]> = if let Some(ctx_str) = derive_key_opt {
            Some(hash_context(ctx_str.as_bytes()))
        } else {
            None
        };

        let input_files = if files.is_empty() {
            vec!["-".to_string()]
        } else {
            files.clone()
        };

        let mut any_error = false;
        let mut outputs: Vec<(String, Vec<u8>)> = Vec::new();

        for fpath in input_files {
            if fpath == "-" {
                if is_keyed {
                    eprintln!("b3sum: -: Cannot open `-` in keyed mode");
                    std::process::exit(1);
                }
                let mut data = Vec::new();
                io::stdin().read_to_end(&mut data).unwrap();
                let out_bytes = if let Some(kw) = key_words {
                    hash_with_xof(&data, &kw, KEYED_HASH, &kw, seek_val, length_val)
                } else if let Some(ctx_cv) = derive_ctx_cv {
                    hash_with_xof(&data, &ctx_cv, DERIVE_KEY_MATERIAL, &ctx_cv, seek_val, length_val)
                } else {
                    hash_with_xof(&data, &IV, 0, &IV, seek_val, length_val)
                };
                outputs.push((fpath, out_bytes));
            } else {
                match std::fs::read(&fpath) {
                    Ok(data) => {
                        let out_bytes = if let Some(kw) = key_words {
                            hash_with_xof(&data, &kw, KEYED_HASH, &kw, seek_val, length_val)
                        } else if let Some(ctx_cv) = derive_ctx_cv {
                            hash_with_xof(&data, &ctx_cv, DERIVE_KEY_MATERIAL, &ctx_cv, seek_val, length_val)
                        } else {
                            hash_with_xof(&data, &IV, 0, &IV, seek_val, length_val)
                        };
                        outputs.push((fpath, out_bytes));
                    }
                    Err(e) => {
                        eprintln!("b3sum: {}: {}", fpath, e);
                        any_error = true;
                    }
                }
            }
        }

        for (fpath, out_bytes) in outputs {
            if is_raw {
                io::stdout().write_all(&out_bytes).unwrap();
            } else {
                let hex = out_bytes.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                if matches.get_flag("no-names") {
                    println!("{}", hex);
                } else if matches.get_flag("tag") {
                    let (esc, needs) = escape_filename(&fpath);
                    if needs {
                        println!("\\BLAKE3 ({}) = {}", esc, hex);
                    } else {
                        println!("BLAKE3 ({}) = {}", fpath, hex);
                    }
                } else {
                    let (esc, needs) = escape_filename(&fpath);
                    if needs {
                        println!("\\{}  {}", hex, esc);
                    } else {
                        println!("{}  {}", hex, fpath);
                    }
                }
            }
        }

        if any_error {
            std::process::exit(1);
        }
    }
}
