    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = rotr(state[d] ^ state[a], 8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 7);
}

fn compress(cv: &[u32; 8], block_words: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut state = [0u32; 16];
    state[0..8].copy_from_slice(cv);
    state[8..12].copy_from_slice(&IV[0..4]);
    state[12] = (counter & 0xFFFFFFFF) as u32;
    state[13] = ((counter >> 32) & 0xFFFFFFFF) as u32;
    state[14] = block_len;
    state[15] = flags;

    let mut schedule = [[0usize; 16]; 7];
    let mut s: Vec<usize> = (0..16).collect();
    for r in 0..7 {
        for i in 0..16 {
            schedule[r][i] = s[i];
        }
        let mut ns = [0usize; 16];
        for i in 0..16 {
            ns[i] = s[PERM[i]];
        }
        s = ns.to_vec();
    }

    let mut m = [0u32; 16];
    for round in 0..7 {
        for i in 0..16 {
            m[i] = block_words[schedule[round][i]];
        }
        g(&mut state, 0, 4, 8, 12, m[0], m[1]);
        g(&mut state, 1, 5, 9, 13, m[2], m[3]);
        g(&mut state, 2, 6, 10, 14, m[4], m[5]);
        g(&mut state, 3, 7, 11, 15, m[6], m[7]);
        g(&mut state, 0, 5, 10, 15, m[8], m[9]);
        g(&mut state, 1, 6, 11, 12, m[10], m[11]);
        g(&mut state, 2, 7, 8, 13, m[12], m[13]);
        g(&mut state, 3, 4, 9, 14, m[14], m[15]);
    }

    let mut out = [0u32; 16];
    for i in 0..8 {
        out[i] = state[i] ^ state[i+8];
        out[i+8] = state[i+8] ^ cv[i];
    }
    out
}

fn bytes_to_words(b: &[u8]) -> [u32; 16] {
    let mut out = [0u32; 16];
    let mut block = [0u8; 64];
    let len = b.len().min(64);
    block[..len].copy_from_slice(&b[..len]);
    for i in 0..16 {
        out[i] = u32::from_le_bytes([block[i*4], block[i*4+1], block[i*4+2], block[i*4+3]]);
    }
    out
