    state[a] = state[a].wrapping_add(state[b]).wrapping_add(mx);
    state[d] = rotr(state[d] ^ state[a], 16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(my);
    state[d] = rotr(state[d] ^ state[a], 8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = rotr(state[b] ^ state[c], 7);
}
fn compress(cv: &[u32; 8], block_words: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 16] {
    let mut state = [0u32; 16];
    state[0..8].copy_from_slice(cv);
    state[8..12].copy_from_slice(&IV[0..4]);
    state[12] = (counter & 0xFFFFFFFF) as u32;
    state[13] = ((counter >> 32) & 0xFFFFFFFF) as u32;
    state[14] = block_len;
    state[15] = flags;
    let mut schedule = [[0usize; 16]; 7];
    let mut s: Vec<usize> = (0..16).collect();
    for r in 0..7 {
        for i in 0..16 { schedule[r][i] = s[i]; }
        let mut ns = [0usize; 16];
        for i in 0..16 { ns[i] = s[PERM[i]]; }
        s = ns.to_vec();
    }
    let mut m = [0u32; 16];
    for round in 0..7 {
        for i in 0..16 { m[i] = block_words[schedule[round][i]]; }
        g(&mut state, 0, 4, 8, 12, m[0], m[1]);
        g(&mut state, 1, 5, 9, 13, m[2], m[3]);
        g(&mut state, 2, 6, 10, 14, m[4], m[5]);
        g(&mut state, 3, 7, 11, 15, m[6], m[7]);
        g(&mut state, 0, 5, 10, 15, m[8], m[9]);
        g(&mut state, 1, 6, 11, 12, m[10], m[11]);
        g(&mut state, 2, 7, 8, 13, m[12], m[13]);
        g(&mut state, 3, 4, 9, 14, m[14], m[15]);
    }
    let mut out = [0u32; 16];
    for i in 0..8 {
        out[i] = state[i] ^ state[i+8];
        out[i+8] = state[i+8] ^ cv[i];
    }
    out
}
fn bytes_to_words(b: &[u8]) -> [u32; 16] {
    let mut out = [0u32; 16];
    let mut block = [0u8; 64];
    let len = b.len().min(64);
    block[..len].copy_from_slice(&b[..len]);
    for i in 0..16 {
        out[i] = u32::from_le_bytes([block[i*4], block[i*4+1], block[i*4+2], block[i*4+3]]);
    }
    out
}
fn words_to_bytes(words: &[u32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(words.len()*4);
    for w in words { out.extend_from_slice(&w.to_le_bytes()); }
    out
}
fn hash_with_xof(data: &[u8], key_words: &[u32; 8], flags: u32, parent_cv: &[u32; 8], seek: u64, length: u64) -> Vec<u8> {
    let chunks: Vec<&[u8]> = if data.is_empty() { vec![&[]] } else { data.chunks(1024).collect() };
    if chunks.len() == 1 {
        let chunk = chunks[0];
        let blocks: Vec<&[u8]> = if chunk.is_empty() { vec![&[]] } else { chunk.chunks(64).collect() };
        let mut cv = *key_words;
        for i in 0..blocks.len()-1 {
            let blk = blocks[i];
            let mut bflags = flags;
            if i == 0 { bflags |= CHUNK_START; }
            let bw = bytes_to_words(blk);
            let out = compress(&cv, &bw, 0, blk.len() as u32, bflags);
            cv = [out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7]];
        }
        let last = blocks[blocks.len()-1];
        let last_bw = bytes_to_words(last);
        let last_len = last.len() as u32;
        let single_block = blocks.len() == 1;
        let mut base = flags;
        if single_block { base |= CHUNK_START; }
        base |= CHUNK_END | ROOT;
        let needed = seek + length;
        let mut out_bytes = Vec::new();
        let mut counter = 0u64;
        while (out_bytes.len() as u64) < needed {
            let out_words = compress(&cv, &last_bw, counter, last_len, base);
            out_bytes.extend_from_slice(&words_to_bytes(&out_words));
            counter += 1;
        }
        out_bytes[seek as usize .. (seek+length) as usize].to_vec()
    } else {
        let mut cvs: Vec<[u32; 8]> = Vec::new();
        for (idx, ch) in chunks.iter().enumerate() {
            let mut cv = *key_words;
            let blocks: Vec<&[u8]> = if ch.is_empty() { vec![&[]] } else { ch.chunks(64).collect() };
            for (i, blk) in blocks.iter().enumerate() {
                let mut bflags = flags;
                if i == 0 { bflags |= CHUNK_START; }
                if i == blocks.len()-1 { bflags |= CHUNK_END; }
                let bw = bytes_to_words(blk);
                let out = compress(&cv, &bw, idx as u64, blk.len() as u32, bflags);
                cv = [out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7]];
            }
            cvs.push(cv);
        }
        let mut cur = cvs;
        let mut root_parent_cv: [u32; 8] = *parent_cv;
        let mut root_block_words: [u32; 16] = [0; 16];
        let mut root_flags: u32 = 0;
        let mut found_root = false;
        while cur.len() > 1 {
            let is_final = cur.len() == 2;
            let mut next = Vec::new();
            let mut i = 0;
            while i < cur.len() {
                if i+1 < cur.len() {
                    if is_final {
                        let left = cur[i];
                        let right = cur[i+1];
                        let mut bw = [0u32; 16];
                        bw[0..8].copy_from_slice(&left);
                        bw[8..16].copy_from_slice(&right);
                        root_block_words = bw;
                        root_flags = PARENT | flags | ROOT;
                        root_parent_cv = *parent_cv;
                        found_root = true;
                        break;
                    } else {
                        let left = cur[i];
                        let right = cur[i+1];
                        let mut bw = [0u32; 16];
                        bw[0..8].copy_from_slice(&left);
                        bw[8..16].copy_from_slice(&right);
                        let pflags = PARENT | flags;
                        let out = compress(parent_cv, &bw, 0, 64, pflags);
                        next.push([out[0], out[1], out[2], out[3], out[4], out[5], out[6], out[7]]);
                    }
                    i += 2;
                } else {
                    next.push(cur[i]);
                    i += 1;
                }
            }
            if found_root { break; }
            cur = next;
        }
        if !found_root {
            let needed = seek + length;
            let mut out_bytes = Vec::new();
            out_bytes.extend_from_slice(&words_to_bytes(&cur[0]));
            while (out_bytes.len() as u64) < needed {
                out_bytes.extend_from_slice(&[0u8; 32]);
            }
            return out_bytes[seek as usize .. (seek+length) as usize].to_vec();
        }
        let needed = seek + length;
        let mut out_bytes = Vec::new();
        let mut counter = 0u64;
        while (out_bytes.len() as u64) < needed {
            let out_words = compress(&root_parent_cv, &root_block_words, counter, 64, root_flags);
            out_bytes.extend_from_slice(&words_to_bytes(&out_words));
            counter += 1;
        }
        out_bytes[seek as usize .. (seek+length) as usize].to_vec()
    }
}
fn hash_context(context: &[u8]) -> [u32; 8] {
    let out = hash_with_xof(context, &IV, DERIVE_KEY_CONTEXT, &IV, 0, 32);
    let mut cv = [0u32; 8];
    for i in 0..8 {
        cv[i] = u32::from_le_bytes([out[i*4], out[i*4+1], out[i*4+2], out[i*4+3]]);
    }
    cv
}
fn escape_filename(name: &str) -> (String, bool) {
    let needs = name.contains('\\') || name.contains('\n') || name.contains('\r');
    if !needs { return (name.to_string(), false); }
    let mut esc = String::new();
    for ch in name.chars() {
        match ch {
            '\\' => esc.push_str("\\\\"),
            '\n' => esc.push_str("\\n"),
            '\r' => esc.push_str("\\r"),
            _ => esc.push(ch),
        }
    }
    (esc, true)
}
fn unescape_filename(esc: &str) -> Result<String, &'static str> {
    let mut out = String::new();
    let mut chars = esc.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('\\') => out.push('\\'),
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some(_) => return Err("Invalid backslash escape"),
                None => return Err("Invalid backslash escape"),
            }
        } else {
            out.push(c);
        }
    }
    Ok(out)
}

fn main() {
    let cmd = Command::new("executable")
        .version("1.8.4")
        .arg(Arg::new("keyed").long("keyed").action(ArgAction::SetTrue).help("Use the keyed mode, reading the 32-byte key from stdin"))
        .arg(Arg::new("derive-key").long("derive-key").value_name("CONTEXT").help("Use the key derivation mode, with the given context string").long_help("Use the key derivation mode, with the given context string\n\nCannot be used with --keyed.").conflicts_with("keyed").conflicts_with("check"))
        .arg(Arg::new("length").short('l').long("length").value_name("LEN").default_value("32").help("The number of output bytes, before hex encoding"))
        .arg(Arg::new("seek").long("seek").value_name("SEEK").default_value("0").help("The starting output byte offset, before hex encoding"))
        .arg(Arg::new("num-threads").long("num-threads").value_name("NUM").help("The maximum number of threads to use").long_help("The maximum number of threads to use\n\nBy default, this is the number of logical cores. If this flag is omitted, or if its value\nis 0, RAYON_NUM_THREADS is also respected."))
        .arg(Arg::new("no-mmap").long("no-mmap").action(ArgAction::SetTrue).help("Disable memory mapping").long_help("Disable memory mapping\n\nCurrently this also disables multithreading."))
        .arg(Arg::new("no-names").long("no-names").action(ArgAction::SetTrue).help("Omit filenames in the output").conflicts_with("check"))
        .arg(Arg::new("raw").long("raw").action(ArgAction::SetTrue).help("Write raw output bytes to stdout, rather than hex").long_help("Write raw output bytes to stdout, rather than hex\n\n--no-names is implied. In this case, only a single input is allowed.").conflicts_with("check"))
        .arg(Arg::new("tag").long("tag").action(ArgAction::SetTrue).help("Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]").conflicts_with("check"))
        .arg(Arg::new("check").short('c').long("check").action(ArgAction::SetTrue).help("Read BLAKE3 sums from the [FILE]s and check them"))
        .arg(Arg::new("quiet").long("quiet").action(ArgAction::SetTrue).help("Skip printing OK for each checked file").long_help("Skip printing OK for each checked file\n\nMust be used with --check.").requires("check"))
        .arg(Arg::new("FILE").value_name("FILE").help("Files to hash, or checkfiles to check").long_help("Files to hash, or checkfiles to check\n\nWhen no file is given, or when - is given, read standard input.").num_args(0..));

    let matches = cmd.get_matches();

    let is_keyed = matches.get_flag("keyed");
    let derive_key_opt = matches.get_one::<String>("derive-key").cloned();
    let is_check = matches.get_flag("check");
    let is_raw = matches.get_flag("raw");

    let files: Vec<String> = matches.get_many::<String>("FILE").map(|v| v.cloned().collect()).unwrap_or_else(Vec::new);

    if is_keyed && files.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <FILE>...");
        eprintln!();
        eprintln!("Usage: executable --keyed <FILE>...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    if is_raw && files.len() > 1 {
        eprintln!("Error: Only one filename can be provided when using --raw");
        std::process::exit(1);
    }

    let length_val: u64 = {
        let s = matches.get_one::<String>("length").unwrap();
        match s.parse::<u64>() {
            Ok(v) => v,
            Err(_) => {
                eprintln!("error: invalid value '{}' for '--length <LEN>': invalid digit found in string", s);
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        }
    };

    let seek_val: u64 = {
        let s = matches.get_one::<String>("seek").unwrap();
        match s.parse::<u64>() {
            Ok(v) => v,
            Err(_) => {
                if s.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found", s);
                    eprintln!();
                    eprintln!("  tip: to pass '{}' as a value, use '-- {}'", s, s);
                    eprintln!();
                    eprintln!("Usage: executable [OPTIONS] [FILE]...");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                } else {
                    eprintln!("error: invalid value '{}' for '--seek <SEEK>': invalid digit found in string", s);
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        }
    };

    if let Some(nt_str) = matches.get_one::<String>("num-threads") {
        if nt_str.parse::<u64>().is_err() {
            eprintln!("error: invalid value '{}' for '--num-threads <NUM>': invalid digit found in string", nt_str);
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if is_check {
        let check_files = if files.is_empty() { vec!["-".to_string()] } else { files.clone() };
        let mut any_failed = false;
        let mut total_failed: u64 = 0;
        let mut checkfile_error = false;

        for cf_path in check_files {
            let content: Vec<u8> = if cf_path == "-" {
                let mut buf = Vec::new();
                io::stdin().read_to_end(&mut buf).unwrap();
                buf
            } else {
                match std::fs::read(&cf_path) {
                    Ok(b) => b,
                    Err(e) => {
                        eprintln!("Error: No such file or directory (os error {})", e.raw_os_error().unwrap_or(2));
                        checkfile_error = true;
                        continue;
                    }
                }
            };
            let text = String::from_utf8_lossy(&content);
            for line in text.lines() {
                if line.is_empty() {
                    eprintln!("b3sum: Empty line");
                    any_failed = true;
                    total_failed += 1;
                    continue;
                }
                let mut is_escaped = false;
                let mut line_to_parse = line;
                if line.starts_with('\\') {
                    is_escaped = true;
                    line_to_parse = &line[1..];
                }

                let mut fname_opt: Option<String> = None;
                let mut hash_opt: Option<String> = None;
                let mut parse_error = false;

                if line_to_parse.starts_with("BLAKE3 (") {
                    if let Some(eq_idx) = line_to_parse.rfind(" = ") {
                        let left = &line_to_parse[..eq_idx];
                        let right = &line_to_parse[eq_idx+3..];
                        if left.starts_with("BLAKE3 (") && left.ends_with(')') {
                            let inner = &left[7..left.len()-1];
                            let fname_res = if is_escaped {
                                unescape_filename(inner)
                            } else {
                                Ok(inner.to_string())
                            };
                            match fname_res {
                                Ok(f) => {
                                    if right.len() != 64 {
                                        eprintln!("b3sum: Invalid hash length");
                                        parse_error = true;
                                    } else if !right.chars().all(|c| c.is_ascii_digit() || (c >= 'a' && c <= 'f')) {
                                        eprintln!("b3sum: Invalid hex");
                                        parse_error = true;
                                    } else {
                                        fname_opt = Some(f);
                                        hash_opt = Some(right.to_string());
                                    }
                                }
                                Err(_) => {
                                    eprintln!("b3sum: Invalid backslash escape");
                                    parse_error = true;
                                }
                            }
                        } else {
                            eprintln!("b3sum: Invalid check line format");
                            parse_error = true;
                        }
                    } else {
                        eprintln!("b3sum: Invalid check line format");
                        parse_error = true;
                    }
                } else {
                    if let Some(idx) = line_to_parse.find("  ") {
                        let hash_part = &line_to_parse[..idx];
                        let file_part = &line_to_parse[idx+2..];
                        if file_part.is_empty() {
                            eprintln!("b3sum: empty file path");
                            parse_error = true;
                        } else if hash_part.len() != 64 {
                            eprintln!("b3sum: Invalid hash length");
                            parse_error = true;
                        } else if !hash_part.chars().all(|c| c.is_ascii_digit() || (c >= 'a' && c <= 'f')) {
                            eprintln!("b3sum: Invalid hex");
                            parse_error = true;
                        } else {
                            let fname_res = if is_escaped {
                                unescape_filename(file_part)
                            } else {
                                Ok(file_part.to_string())
                            };
                            match fname_res {
                                Ok(f) => {
                                    fname_opt = Some(f);
                                    hash_opt = Some(hash_part.to_string());
                                }
                                Err(_) => {
                                    eprintln!("b3sum: Invalid backslash escape");
                                    parse_error = true;
                                }
                            }
                        }
                    } else {
                        eprintln!("b3sum: Invalid check line format");
                        parse_error = true;
                    }
                }

                if parse_error {
                    any_failed = true;
                    total_failed += 1;
                    continue;
                }

                if let (Some(fname), Some(expected_hash)) = (fname_opt, hash_opt) {
                    let data = match std::fs::read(&fname) {
                        Ok(d) => d,
                        Err(e) => {
                            let (esc, needs) = escape_filename(&fname);
                            let display = if needs { format!("\\{}", esc) } else { esc };
                            println!("{}: FAILED (No such file or directory (os error {}))", display, e.raw_os_error().unwrap_or(2));
                            any_failed = true;
                            total_failed += 1;
                            continue;
                        }
                    };
                    let computed = hash_with_xof(&data, &IV, 0, &IV, seek_val, 32);
                    let computed_hex = computed.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                    let (esc, needs) = escape_filename(&fname);
                    let display = if needs { format!("\\{}", esc) } else { esc };
                    if computed_hex == expected_hash {
                        if !matches.get_flag("quiet") {
                            println!("{}: OK", display);
                        }
                    } else {
                        println!("{}: FAILED", display);
                        any_failed = true;
                        total_failed += 1;
                    }
                }
            }
        }
        if any_failed {
            eprintln!("b3sum: WARNING: {} computed checksum did NOT match", total_failed);
            std::process::exit(1);
        }
        if checkfile_error {
            std::process::exit(1);
        }
        std::process::exit(0);
    } else {
        let key_words: Option<[u32; 8]> = if is_keyed {
            let mut key_data = Vec::new();
            io::stdin().read_to_end(&mut key_data).unwrap();
            if key_data.len() > 32 {
                eprintln!("Error: read more than 32 key bytes from stdin");
                std::process::exit(1);
            }
            if key_data.len() != 32 {
                eprintln!("Error: expected 32 key bytes from stdin, found {}", key_data.len());
                std::process::exit(1);
            }
            let mut kw = [0u32; 8];
            for i in 0..8 {
                kw[i] = u32::from_le_bytes([key_data[i*4], key_data[i*4+1], key_data[i*4+2], key_data[i*4+3]]);
            }
            Some(kw)
        } else {
            None
        };

        let derive_ctx_cv: Option<[u32; 8]> = if let Some(ctx_str) = derive_key_opt {
            Some(hash_context(ctx_str.as_bytes()))
        } else {
            None
        };

        let input_files = if files.is_empty() {
            vec!["-".to_string()]
        } else {
            files.clone()
        };

        let mut any_error = false;

        for fpath in input_files {
            if fpath == "-" {
                if is_keyed {
                    eprintln!("b3sum: -: Cannot open `-` in keyed mode");
                    std::process::exit(1);
                }
                let mut data = Vec::new();
                io::stdin().read_to_end(&mut data).unwrap();
                let out_bytes = if let Some(kw) = key_words {
                    hash_with_xof(&data, &kw, KEYED_HASH, &kw, seek_val, length_val)
                } else if let Some(ctx_cv) = derive_ctx_cv {
                    hash_with_xof(&data, &ctx_cv, DERIVE_KEY_MATERIAL, &ctx_cv, seek_val, length_val)
                } else {
                    hash_with_xof(&data, &IV, 0, &IV, seek_val, length_val)
                };
                if is_raw {
                    io::stdout().write_all(&out_bytes).unwrap();
                } else {
                    let hex = out_bytes.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                    if matches.get_flag("no-names") {
                        println!("{}", hex);
                    } else if matches.get_flag("tag") {
                        println!("BLAKE3 (-) = {}", hex);
                    } else {
                        println!("{}  -", hex);
                    }
                }
            } else {
                match std::fs::read(&fpath) {
                    Ok(data) => {
                        let out_bytes = if let Some(kw) = key_words {
                            hash_with_xof(&data, &kw, KEYED_HASH, &kw, seek_val, length_val)
                        } else if let Some(ctx_cv) = derive_ctx_cv {
                            hash_with_xof(&data, &ctx_cv, DERIVE_KEY_MATERIAL, &ctx_cv, seek_val, length_val)
                        } else {
                            hash_with_xof(&data, &IV, 0, &IV, seek_val, length_val)
                        };
                        if is_raw {
                            io::stdout().write_all(&out_bytes).unwrap();
                        } else {
                            let hex = out_bytes.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                            if matches.get_flag("no-names") {
                                println!("{}", hex);
                            } else if matches.get_flag("tag") {
                                let (esc, needs) = escape_filename(&fpath);
                                if needs {
                                    println!("\\BLAKE3 ({}) = {}", esc, hex);
                                } else {
                                    println!("BLAKE3 ({}) = {}", fpath, hex);
                                }
                            } else {
                                let (esc, needs) = escape_filename(&fpath);
                                if needs {
                                    println!("\\{}  {}", hex, esc);
                                } else {
                                    println!("{}  {}", hex, fpath);
                                }
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("b3sum: {}: {}", fpath, e);
                        any_error = true;
                    }
                }
            }
        }

        if any_error {
            std::process::exit(1);
        }
    }
}
